values.content:
Prepare board meeting materials.

Company: {{ $json.companyName }}
Meeting date: {{ $json.meetingDate }}
Period: {{ $json.quarterOrPeriod || 'not specified' }}
Board members: {{ $json.boardMembers.join(', ') || 'not specified' }}
Company context: {{ $json.companyContext || 'not specified' }}

Key metrics:
{{ Object.entries($json.keyMetrics||{}).map(([k,v])=>k+': '+v).join('\n') || 'not provided' }}

Agenda topics:
{{ $json.agendaTopics.join('\n') || 'not specified' }}

Big decisions needed from board:
{{ $json.bigDecisionsNeeded.join('\n') || 'none specified' }}

Known concerns or weak spots:
{{ $json.knownConcerns || 'none specified' }}

Previous action items:
{{ $json.previousActionItems.join('\n') || 'none specified' }}

Return JSON:
{"meeting_narrative":"2-3 sentences: the story arc of this board meeting — what the founder wants the board to understand and believe by the end","anticipated_questions":[{"question":"a hard question a board member is likely to ask","why_theyll_ask":"","suggested_answer":"honest, direct answer — not spin","supporting_data_needed":"what data point to have ready"}],"metrics_talking_points":[{"metric":"","value":"","context":"how to frame this number — trend, comparison, what drove it","if_asked_why":"honest explanation if the board pushes on this number"}],"weak_points_to_address_proactively":[{"weak_point":"","proactive_framing":"how to raise this before the board does, showing awareness and a plan"}],"decision_prep":[{"decision":"","recommendation":"what the founder should recommend","rationale":"","alternative_view":"the strongest counter-argument, so founder is prepared for pushback"}],"previous_action_item_status":[{"item":"","suggested_update":"how to report on this if not fully resolved"}],"suggested_agenda_order":["topics in recommended order with rationale for sequencing"],"pre_read_summary":"a 150-word summary suitable for the board pre-read email","closing_ask":"what specifically to ask the board for at the end of the meeting"}
